"""Build a navigation graph from HTML generated by Verso.

The rendered site is an input artefact, not a second source of truth. This
module emits stable page/anchor nodes, structural containment edges, and only
explicit cross-reference/citation edges. It does not infer proof,
implementation, testing, or epistemic-status relations.

Outputs are navigation/index.html and navigation/graph.json, plus one
contextual entry injected into every rendered HTML page outside the navigation
output directory. Editorial explanations are authored separately and attached
only to explicit targets that resolve in the rendered site.
"""
from __future__ import annotations

import argparse
import hashlib
import html
import json
import os
import posixpath
import re
import sys
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import quote, unquote, urljoin, urlsplit

try:
    # Package import under unittest discovery.
    from .navigation_explanations import EXPLANATION_CATALOG
except ImportError:
    # Direct execution by the verification workflow.
    from navigation_explanations import EXPLANATION_CATALOG


VOID_TAGS = {
    "area", "base", "br", "col", "embed", "hr", "img", "input", "link",
    "meta", "param", "source", "track", "wbr",
}
HEADING_TAGS = {"h1", "h2", "h3", "h4", "h5", "h6"}
SEMANTIC_CLASSES = {
    "k7-figure": "figure",
    "k7-table": "table",
    "k7-listing": "listing",
    "k7-theorem": "statement",
}


class Element:
    """Small DOM node for querying the structure and text of rendered HTML."""

    def __init__(self, tag: str, attrs: dict[str, str | None], parent: Element | None):
        """Store parsed attributes and parent/child links."""
        self.tag = tag
        self.attrs = attrs
        self.parent = parent
        self.children: list[Element | str] = []

    def text(self) -> str:
        """Return normalized visible text, ignoring non-reader-facing elements."""
        if self.tag in {"script", "style", "noscript"}:
            return ""
        value = "".join(child.text() if isinstance(child, Element) else child for child in self.children)
        return " ".join(value.split())


class DOMBuilder(HTMLParser):
    """Build the minimal DOM tree needed for node and relation extraction."""

    def __init__(self) -> None:
        """Initialize a synthetic root so traversal always has a parent."""
        super().__init__(convert_charrefs=True)
        self.root = Element("document", {}, None)
        self.stack = [self.root]

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        element = Element(tag, dict(attrs), self.stack[-1])
        self.stack[-1].children.append(element)
        if tag not in VOID_TAGS:
            self.stack.append(element)

    def handle_startendtag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        element = Element(tag, dict(attrs), self.stack[-1])
        self.stack[-1].children.append(element)

    def handle_endtag(self, tag: str) -> None:
        for index in range(len(self.stack) - 1, 0, -1):
            if self.stack[index].tag == tag:
                del self.stack[index:]
                break

    def handle_data(self, data: str) -> None:
        self.stack[-1].children.append(data)


def descendants(root: Element):
    """Yield all descendant elements in document order."""
    for child in root.children:
        if isinstance(child, Element):
            yield child
            yield from descendants(child)


def classes(element: Element) -> set[str]:
    """Return the whitespace-separated CSS classes as a set."""
    return set((element.attrs.get("class") or "").split())


def has_class_ancestor(element: Element, class_name: str) -> Element | None:
    """Find the nearest ancestor carrying the requested CSS class."""
    current = element.parent
    while current is not None:
        if class_name in classes(current):
            return current
        current = current.parent
    return None


def nearest_semantic_ancestor(element: Element, semantic_elements: dict[int, str]) -> str | None:
    """Resolve the closest ancestor already registered as a semantic node."""
    current = element.parent
    while current is not None:
        found = semantic_elements.get(id(current))
        if found is not None:
            return found
        current = current.parent
    return None


def first_descendant_text(element: Element, class_name: str) -> str:
    """Return the first non-empty descendant text marked by a CSS class."""
    for child in descendants(element):
        if class_name in classes(child):
            text = child.text()
            if text:
                return text
    return ""


def semantic_kind(element: Element) -> str | None:
    """Classify blocks through explicit renderer markers, not filename heuristics."""
    found = classes(element)
    for class_name, kind in SEMANTIC_CLASSES.items():
        if class_name in found:
            return kind
    if element.tag == "li" and element.attrs.get("id") and has_class_ancestor(element, "k7-bib"):
        return "bibliography"
    return None


def make_node(
    node_id: str, kind: str, label: str, url: str, page: str, description: str = ""
) -> dict[str, str]:
    """Construct the normalized node record shared by all extraction paths."""
    return {
        "id": node_id,
        "kind": kind,
        "label": label or node_id,
        "description": description,
        "url": url,
        "page": page,
    }


def section_context(elements: list[Element], heading: Element, max_chars: int = 480) -> str:
    """Return a bounded excerpt of prose immediately following a heading.

    The excerpt is derived from rendered HTML, not treated as a definition or
    as evidence for a scientific relation. Stop at the next heading so a
    subsection's text is not presented as the parent section's introduction.
    """
    try:
        heading_index = next(index for index, element in enumerate(elements) if element is heading)
    except StopIteration:
        return ""

    excerpts: list[str] = []
    used = 0
    for element in elements[heading_index + 1:]:
        if element.tag in HEADING_TAGS:
            break
        if element.tag != "p":
            continue

        current: Element | None = element
        in_navigation_entry = False
        while current is not None:
            if current.attrs.get("id") == "k7pl-navigation-entry":
                in_navigation_entry = True
                break
            current = current.parent
        if in_navigation_entry:
            continue

        text = element.text()
        if not text:
            continue
        remaining = max_chars - used
        if remaining <= 0:
            break
        if len(text) > remaining:
            trimmed = text[:remaining].rsplit(" ", 1)[0].rstrip()
            text = (trimmed or text[:remaining].rstrip()) + "…"
        excerpts.append(text)
        used += len(text) + 1
        if used >= max_chars or text.endswith("…"):
            break
    return " ".join(excerpts)


def normalize_target(
    page: str, base_href: str, href: str, available_pages: set[str] | None = None
) -> str | None:
    """Resolve an href to a site-relative page/fragment, or ignore external URLs.

    Verso's base URL affects relative links. Directory targets are mapped to
    index.html only when that rendered file actually exists.
    """
    parts = urlsplit(href.strip())
    if parts.scheme or parts.netloc or href.strip().startswith(("mailto:", "data:", "javascript:")):
        return None
    base = urljoin(page, base_href or ".")
    resolved = urlsplit(urljoin(base, href.strip()))
    target_path = posixpath.normpath(unquote(resolved.path)).lstrip("/")
    if target_path in {"", "."}:
        target_path = page
    if target_path == ".." or target_path.startswith("../"):
        return None
    # Verso may emit "chapter/#label", although the multi-page renderer writes
    # the document to "chapter/index.html". Resolve only against rendered files.
    if available_pages is not None and target_path not in available_pages:
        index_target = posixpath.join(target_path, "index.html")
        if index_target in available_pages:
            target_path = index_target
    fragment = unquote(resolved.fragment)
    return f"{target_path}#{fragment}" if fragment else target_path


def parse_page(path: Path, site_root: Path) -> dict:
    """Parse a rendered page and index its title, base URL, elements and anchors."""
    page = path.relative_to(site_root).as_posix()
    parser = DOMBuilder()
    parser.feed(path.read_text(encoding="utf-8"))
    elements = list(descendants(parser.root))
    base_href = next(
        (element.attrs.get("href") or "." for element in elements if element.tag == "base"),
        ".",
    )
    title = next((element.text() for element in elements if element.tag == "h1" and element.text()), "")
    if not title:
        title = next((element.text() for element in elements if element.tag == "title" and element.text()), Path(page).stem)

    return {
        "path": page,
        "root": parser.root,
        "elements": elements,
        "base_href": base_href,
        "title": title,
        "element_by_id": {
            element.attrs["id"]: element
            for element in elements
            if element.attrs.get("id")
        },
    }


def build_graph(site_root: Path) -> dict:
    """Extract nodes and supported edges from every rendered HTML page.

    All chapter pages participate. Navigation output is excluded to prevent the
    generated UI from becoming input to its own graph. Unresolved explicit links
    fail the build rather than being silently dropped.
    """
    site_root = site_root.resolve()
    if not site_root.is_dir():
        raise ValueError(f"site output directory does not exist: {site_root}")

    page_paths = sorted(
        path for path in site_root.rglob("*.html")
        if path.relative_to(site_root).as_posix() != "navigation/index.html"
        and "navigation" not in path.relative_to(site_root).parts
    )
    if not page_paths:
        raise ValueError(f"no rendered HTML pages found under {site_root}")

    pages = {record["path"]: record for record in (parse_page(path, site_root) for path in page_paths)}
    available_pages = set(pages)
    nodes: dict[str, dict[str, str]] = {}
    anchor_to_node: dict[str, str] = {}
    element_to_node: dict[tuple[str, int], str] = {}
    element_heading: dict[tuple[str, int], str] = {}
    semantic_elements: dict[tuple[str, int], dict[int, str]] = {}
    containment: list[dict] = []
    link_candidates: list[dict] = []
    target_keys: set[str] = set()

    for page, record in pages.items():
        elements = record["elements"]
        page_node_id = page
        nodes[page_node_id] = make_node(page_node_id, "document", record["title"], page, page)

        semantic_map: dict[int, str] = {}
        semantic_elements[(page, 0)] = semantic_map
        current_heading: str | None = None
        heading_stack: list[tuple[int, str]] = []
        heading_number = 0

        for element in elements:
            key = (page, id(element))
            if element.tag in HEADING_TAGS:
                level = int(element.tag[1])
                while heading_stack and heading_stack[-1][0] >= level:
                    heading_stack.pop()
                heading_number += 1
                element_id = element.attrs.get("id")
                node_id = f"{page}#{element_id}" if element_id else f"{page}#heading-{heading_number}"
                label = element.text() or f"Section {heading_number}"
                url = f"{page}#{element_id}" if element_id else page
                description = section_context(elements, element) or element.text()
                nodes[node_id] = make_node(node_id, "section", label, url, page, description)
                if element_id:
                    anchor_to_node[f"{page}#{element_id}"] = node_id
                if heading_stack:
                    containment.append({
                        "source": heading_stack[-1][1],
                        "target": node_id,
                        "kind": "contains",
                        "provenance": {"page": page, "source": "heading hierarchy"},
                    })
                heading_stack.append((level, node_id))
                current_heading = node_id

            element_heading[key] = current_heading or page_node_id

            kind = semantic_kind(element)
            element_id = element.attrs.get("id")
            if kind and element_id:
                node_id = f"{page}#{element_id}"
                label = ""
                if kind == "figure":
                    label = first_descendant_text(element, "k7-caption")
                    if not label:
                        image = next((child for child in descendants(element) if child.tag == "img"), None)
                        label = (image.attrs.get("alt") or "") if image else ""
                elif kind in {"table", "listing"}:
                    label = first_descendant_text(element, "k7-caption")
                elif kind == "statement":
                    label = first_descendant_text(element, "k7-thm-head") or first_descendant_text(element, "k7-stm-head")
                elif kind == "bibliography":
                    label = element.text()
                description = element.text()
                if kind == "figure":
                    image = next((child for child in descendants(element) if child.tag == "img"), None)
                    alt = (image.attrs.get("alt") or "").strip() if image else ""
                    if alt:
                        description = alt + (" — " + description if description else "")
                nodes[node_id] = make_node(
                    node_id, kind, label, f"{page}#{element_id}", page, description
                )
                semantic_map[id(element)] = node_id
                element_to_node[key] = node_id
                anchor_to_node[f"{page}#{element_id}"] = node_id
                if current_heading and current_heading != node_id:
                    containment.append({
                        "source": current_heading,
                        "target": node_id,
                        "kind": "contains",
                        "provenance": {"page": page, "source": "document structure"},
                    })

            if element.tag == "span" and "k7-anchor" in classes(element) and element_id:
                semantic_parent = nearest_semantic_ancestor(element, semantic_map)
                section_node = semantic_parent or current_heading
                if section_node:
                    anchor_to_node[f"{page}#{element_id}"] = section_node
                    if section_node in nodes and nodes[section_node]["kind"] == "section":
                        nodes[section_node]["url"] = f"{page}#{element_id}"
                else:
                    node_id = f"{page}#{element_id}"
                    nodes.setdefault(node_id, make_node(node_id, "anchor", element_id, f"{page}#{element_id}", page))
                    anchor_to_node[f"{page}#{element_id}"] = node_id

            if element_id and element_id.startswith(("lbl-", "bib-")):
                target = f"{page}#{element_id}"
                if target not in anchor_to_node:
                    semantic_parent = nearest_semantic_ancestor(element, semantic_map)
                    node_id = semantic_parent or current_heading or f"{page}#{element_id}"
                    if node_id not in nodes:
                        nodes[node_id] = make_node(node_id, "anchor", element_id, target, page)
                    anchor_to_node[target] = node_id

        for element in elements:
            classes_here = classes(element)
            in_citation = has_class_ancestor(element, "k7-cite") is not None
            if element.tag != "a" or not element.attrs.get("href"):
                continue
            if "k7-ref" not in classes_here and not in_citation:
                continue
            href = element.attrs["href"] or ""
            target = normalize_target(page, record["base_href"], href, available_pages)
            if target is None:
                continue
            target_keys.add(target)
            semantic_source = nearest_semantic_ancestor(element, semantic_map)
            source = semantic_source or element_heading.get((page, id(element))) or page_node_id
            link_candidates.append({
                "source": source,
                "target_key": target,
                "kind": "cites" if in_citation else "references",
                "provenance": {
                    "page": page,
                    "source_node": source,
                    "link_text": element.text(),
                    "href": href,
                },
            })

    # Resolve targets that are explicit anchors but do not belong to a known
    # figure, statement, section, or bibliography entry.
    for target in sorted(target_keys):
        if target in anchor_to_node or target in nodes:
            continue
        if "#" not in target:
            if target in pages:
                anchor_to_node[target] = target
            continue
        target_page, fragment = target.split("#", 1)
        record = pages.get(target_page)
        element = record["element_by_id"].get(fragment) if record else None
        if element is None or record is None:
            continue
        page_node_id = target_page
        node_id = target
        label = element.text() or fragment
        nodes[node_id] = make_node(node_id, "anchor", label, target, target_page)
        anchor_to_node[target] = node_id

    edges = list(containment)
    unresolved: list[dict] = []
    for candidate in link_candidates:
        target_id = anchor_to_node.get(candidate["target_key"])
        if target_id is None:
            unresolved.append({
                "page": candidate["provenance"]["page"],
                "href": candidate["provenance"]["href"],
                "target": candidate["target_key"],
                "link_text": candidate["provenance"]["link_text"],
            })
            continue
        source_id = candidate["source"]
        if source_id not in nodes:
            unresolved.append({
                "page": candidate["provenance"]["page"],
                "href": candidate["provenance"]["href"],
                "target": candidate["target_key"],
                "reason": f"missing source node {source_id}",
            })
            continue
        if target_id not in nodes:
            unresolved.append({
                "page": candidate["provenance"]["page"],
                "href": candidate["provenance"]["href"],
                "target": candidate["target_key"],
                "reason": f"missing target node {target_id}",
            })
            continue
        edge_key = json.dumps([source_id, target_id, candidate["kind"], candidate["provenance"]["page"], candidate["provenance"]["link_text"]], ensure_ascii=False)
        edge_id = hashlib.sha256(edge_key.encode("utf-8")).hexdigest()[:16]
        edges.append({
            "id": edge_id,
            "source": source_id,
            "target": target_id,
            "kind": candidate["kind"],
            "provenance": candidate["provenance"],
        })

    if unresolved:
        examples = "\n".join(
            f"  - {item.get('page')}: {item.get('href')} -> {item.get('target', item.get('reason', 'unresolved'))}"
            for item in unresolved[:12]
        )
        raise ValueError(f"{len(unresolved)} explicit internal navigation links could not be resolved:\n{examples}")

    graph = {
        "schema_version": 1,
        "generated_from": "rendered Verso HTML; only explicit cross-references and citation links are used",
        "summary": {
            "pages": len(pages),
            "nodes": len(nodes),
            "edges": len(edges),
            "references": sum(edge["kind"] == "references" for edge in edges),
            "citations": sum(edge["kind"] == "cites" for edge in edges),
            "containment": sum(edge["kind"] == "contains" for edge in edges),
        },
        "nodes": sorted(nodes.values(), key=lambda node: (node["kind"], node["label"].casefold(), node["id"])),
        "edges": edges,
        "unresolved_links": unresolved,
    }
    graph["explanations"] = resolve_authored_explanations(graph["nodes"])
    return graph


def resolve_authored_explanations(nodes: list[dict[str, str]]) -> list[dict]:
    """Attach authored, non-normative explanations to explicit rendered targets.

    The catalog supplies the prose and canonical source links. Matching a target
    does not create graph edges or make the explanation a normative source.
    A page present without its requested target is a generation error.
    """
    explanations: list[dict] = []
    for spec in EXPLANATION_CATALOG:
        source_url = spec["target_url"]
        source_page = source_url.split("#", 1)[0]
        document_nodes = [
            node["id"] for node in nodes
            if node.get("kind") == "document" and node.get("page") == source_page
        ]
        # Unit fixtures intentionally model a subset of the publication.
        if not document_nodes:
            continue
        target_nodes = [node["id"] for node in nodes if node.get("url") == source_url]
        if not target_nodes:
            raise ValueError(
                f"authored explanation target does not resolve to a rendered node: {source_url}"
            )
        explanation = {key: value for key, value in spec.items() if key != "target_url"}
        explanation["target_node_ids"] = sorted(set(document_nodes + target_nodes))
        explanations.append(explanation)
    return explanations


